describe('Logout from Side Menu', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
  });

  it('should successfully log out from the side menu and return to login page', () => {
    // Verify user is logged in
    cy.get('[data-testid="inventory-container"]').should('be.visible');
    cy.get('[data-testid="inventory-list"]').should('be.visible');
    cy.get('[data-testid="inventory-item-name"]').first().should('contain', 'Sauce Labs Backpack');

    // Open side menu
    cy.get('[data-testid="react-burger-menu-btn"]').click();
    cy.get('[data-testid="inventory-sidebar-link"]').should('be.visible');

    // Click logout link
    cy.get('[data-testid="logout-sidebar-link"]').click();

    // Verify logout success - redirected to login page
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-container"]').should('be.visible');
    cy.get('[data-testid="username"]').should('be.visible');
    cy.get('[data-testid="password"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');
  });

  it('should handle logout when side menu is not open', () => {
    // Verify user is logged in
    cy.get('[data-testid="inventory-container"]').should('be.visible');

    // Attempt to click logout without opening menu (should not exist or be visible)
    cy.get('[data-testid="logout-sidebar-link"]').should('not.exist');

    // Open side menu
    cy.get('[data-testid="react-burger-menu-btn"]').click();
    cy.get('[data-testid="inventory-sidebar-link"]').should('be.visible');

    // Verify logout link is now visible
    cy.get('[data-testid="logout-sidebar-link"]').should('be.visible');

    // Click logout
    cy.get('[data-testid="logout-sidebar-link"]').click();

    // Verify logout success
    cy.url().should('include', '/login');
    cy.get('[data-testid="login-container"]').should('be.visible');
    cy.get('[data-testid="username"]').should('be.visible');
  });
});
